mapper.select:
SELECT *
FROM shopion.tOrdExcelUploadDetail
WHERE UploadId = #{uploadId}
AND UploadDetailNo = #{uploadDetailNo}

mapper.update:
UPDATE shopion.tOrdExcelUploadDetail SET
    ResultState = #{resultState}, ResultMsg = #{resultMsg}, OrderNo = #{orderNo},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE UploadId = #{uploadId}
AND UploadDetailNo = #{uploadDetailNo}

mapper.delete:
DELETE FROM shopion.tOrdExcelUploadDetail
WHERE UploadId = #{uploadId}
AND UploadDetailNo = #{uploadDetailNo}
